node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const orderId = '#W4705780';
const oldItemId = '9716794911';
const newItemId = '2364909101';
const paymentMethodId = 'credit_card_5360334';

// Get the new variant details
const newVariant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get(newItemId);
const newOptions = JSON.parse(newVariant.options || '{}');
const newPrice = newVariant.price;

// Get the old order item
const oldItem = db.prepare('SELECT * FROM order_items WHERE order_id = ? AND item_id = ?').get(orderId, oldItemId);
const oldPrice = oldItem.unit_price;
const diffPrice = Math.round((newPrice - oldPrice) * 100) / 100;

console.log('Old price:', oldPrice, 'New price:', newPrice, 'Diff:', diffPrice);

// Update the order item
db.prepare('UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE oi_id = ?').run(
  newItemId, newPrice, JSON.stringify(newOptions), oldItem.oi_id
);

// Update the order status
db.prepare('UPDATE orders SET status = ? WHERE order_id = ?').run('pending (item modified)', orderId);

// Add the refund payment record (diff is negative, so it's a refund)
db.prepare('INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)').run(
  orderId, 'refund', Math.abs(diffPrice), paymentMethodId
);

// Verify the changes
const updatedOrder = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
const updatedItems = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
const updatedPayments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);

console.log('\n--- Updated Order ---');
console.log('Status:', updatedOrder.status);
console.log('\nItems:');
updatedItems.forEach(i => {
  console.log('  -', i.name, '| Variant:', i.item_id, '| Price:', i.unit_price, '| Options:', i.options);
});
console.log('\nPayment History:');
updatedPayments.forEach(p => {
  console.log('  -', p.transaction_type, '| Amount:', p.amount, '| Method:', p.payment_method_id);
});

db.close();
"
